// Signs GET /automation/overdue-loans. Env: N8N_TO_CONVEX_SECRET.
const crypto = require("crypto");

const path = "/automation/overdue-loans";
const t = Math.floor(Date.now() / 1000);
const v1 = crypto
  .createHmac("sha256", $env.N8N_TO_CONVEX_SECRET)
  .update(`${t}.GET.${path}.`)
  .digest("hex");

return [{ json: { path, signature: `t=${t},v1=${v1}` } }];

// One item per reminder, with the email Resend should send.
// Env: EMAIL_FROM, APP_URL.
const dueLabel = (iso) =>
  new Intl.DateTimeFormat("en", { weekday: "short", month: "short", day: "numeric", timeZone: "UTC" }).format(new Date(`${iso}T00:00:00Z`));
const { reminders } = $input.first().json;
const link = `${$env.APP_URL ?? "http://localhost:3000"}/requests`;

return reminders.map((reminder) => ({
  json: {
    reminderKey: reminder.reminderKey,
    email: {
      from: $env.EMAIL_FROM,
      to: [reminder.recipient.email],
      subject: `Reminder: please return the ${reminder.tool.name}`,
      text:
        `Hi ${reminder.recipient.firstName},\n\n` +
        `The ${reminder.tool.name} was due back on ${dueLabel(reminder.loan.endDate)} ` +
        `(${reminder.daysOverdue} day${reminder.daysOverdue === 1 ? "" : "s"} ago). ` +
        `Please arrange the return with the lender.\n\n${link}\n\n— LendLoop`,
    },
  },
}));

// Runs once per item. Signs the reminder write-back for POST /automation/reminders.
// STATUS is replaced at build time ("sent" or "failed"). Env: N8N_TO_CONVEX_SECRET.
const crypto = require("crypto");

const STATUS = "sent";
const path = "/automation/reminders";
const { reminderKey } = $("Split reminders").item.json;
const detail = STATUS === "failed" ? String($json.error?.message ?? "send failed").slice(0, 500) : undefined;
const body = JSON.stringify(detail === undefined ? { reminderKey, status: STATUS } : { reminderKey, status: STATUS, detail });
const t = Math.floor(Date.now() / 1000);
const v1 = crypto
  .createHmac("sha256", $env.N8N_TO_CONVEX_SECRET)
  .update(`${t}.POST.${path}.${body}`)
  .digest("hex");

return { json: { path, body, signature: `t=${t},v1=${v1}` } };

